def compute(vars):
    doubtful_receivables = vars["v1"]
    trade_receivables = vars["v2"]

    if trade_receivables == 0:
        return None

    doubtful_percentage = (-doubtful_receivables / trade_receivables) * 100

    return {
        "value": doubtful_percentage,
        "trace": {
            "doubtful_receivables": doubtful_receivables,
            "trade_receivables": trade_receivables,
            "calculation": "(-v1 / v2) * 100",
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
